Item.method_code:
const {
	getState,
	itemType,
	rows,
	polySources,
	commandFactory
} = options;
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(itemType.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return itemType;
};
const commandAlias = target['command_alias@keyed_name'];
const { grid } = getState();
const selectedRows = grid.selectedRows.map(rowId => {
	const item = rows.get(rowId);
	const itemType = getItemType(item);
	const deleteCommand = commandFactory(commandAlias, {
		...options,
		item,
		itemType,
		itemTypeName: itemType.name
	});
	const isDeleteCommandAllowed = deleteCommand.canExecute();

	return {
		isDeleteCommandAllowed,
		isVersionable: itemType.is_versionable === '1',
		isFunctionDisabled: window.isFunctionDisabled(itemTypeName, 'Delete')
	};
});

const hidden = selectedRows.some(row => row.isVersionable);
if (hidden) {
	return { hidden };
}

const disabled = selectedRows.every(row => !row.isDeleteCommandAllowed || row.isFunctionDisabled);

return {
	disabled,
	hidden: false
};
